SELECT project_id, schema_text, layout_json, version, updated_at
FROM db_model_document
WHERE project_id = #{projectId}

SELECT project_id, category_id, category_name, schema_text, layout_json, version, updated_at
FROM db_model_category_document
WHERE project_id = #{projectId}
  AND category_id = #{categoryId}
  AND deleted = FALSE
